import{t,subscribeLanguage}from './i18n.js';
import{uiLeaf,uiAttribute,uiTextAttributes,setUiMessage,uiMessage,uiError,setUiAttribute}from './ui.js';
import{paintLessonsUi,bindLessonsUi,lessonDateLabel,lessonDateMarkup,lessonDueMarkup,lessonErrorMessage,lessonErrorText,lessonUiError}from './lessons-ui.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>{if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return null;const time=Date.parse(value+'T12:00:00Z');return Number.isFinite(time)&&new Date(time).toISOString().slice(0,10)===value?value:null;};
const valid=h=>h&&typeof h.text==='string'&&h.text.trim()&&h.text.length<=2000;
export function homeworkMarkup(homework){
 if(!valid(homework))return '';
 const due=date(homework.dueDate);
 return "<section class=\"lesson-homework-card\" "+uiAttribute("lessonUi.homeworkTitle",{},"aria-label")+"><h3>"+uiLeaf("lessonUi.homeworkTitle")+"</h3><p class=\"lesson-homework-text\" dir=\"auto\" translate=\"no\">"+esc(homework.text)+'</p>'+(due?'<p class="lesson-homework-due">'+lessonDueMarkup(due)+'</p>':'')+'</section>';
}
export function mountHomeworkEditor(root,{lesson,onSave,onCancel=()=>{}}){
 let disposed=false,readingEditor=null,readingLoading=null,readingCleared=false;const initial=valid(lesson.homework)?lesson.homework:null,minimum=date(lesson.date);
 root.innerHTML="<form class=\"lesson-homework-editor\"><h2>"+uiLeaf("lessonUi.homeworkTitle")+"</h2><p translate=\"no\" dir=\"auto\">"+esc(lesson.title)+"</p><label>"+uiLeaf("lessonUi.homeworkTask")+"<textarea name=\"homework\" translate=\"no\" dir=\"auto\" rows=\"5\" maxlength=\"2000\" "+uiAttribute("lessonUi.homeworkPlaceholder",{},"placeholder")+">"+esc(initial?.text||'')+"</textarea></label><small>"+uiLeaf("lessonUi.homeworkLengthHelp")+"</small><label>"+uiLeaf("lessonUi.homeworkDueOptional")+"<input name=\"dueDate\" type=\"date\" dir=\"ltr\""+(minimum?' min="'+minimum+'"':'')+' value="'+esc(date(initial?.dueDate)||'')+"\"></label><div data-reading-editor><button type=\"button\" class=\"button secondary\" data-add-reading>"+uiLeaf("lessonUi.homeworkReadingOptional")+"</button></div><p role=\"alert\" class=\"lesson-homework-error\"></p><div class=\"button-row\"><button class=\"button\" type=\"submit\">"+uiLeaf("lessonUi.homeworkSave")+"</button><button class=\"button secondary\" type=\"button\" data-cancel>"+uiLeaf("lessonUi.homeworkClose")+"</button>"+(initial?"<button class=\"lesson-text-button\" type=\"button\" data-clear>"+uiLeaf("lessonUi.homeworkRemove")+"</button>":'')+'</div></form>';
 const form=root.querySelector('form'),button=form.querySelector('[type=submit]'),text=form.querySelector('textarea'),due=form.querySelector('input'),error=form.querySelector('[role=alert]');
 const readingRoot=form.querySelector('[data-reading-editor]');const openReading=(initial,createDefault=false)=>{if(readingLoading)return readingLoading;readingLoading=import('./reading-check-ui.js').then(module=>{if(disposed||!root.isConnected)return;readingEditor=module.mountReadingCheckEditor(readingRoot,{initial:readingCleared?null:createDefault?{version:1,letterId:'mim',count:10,prompts:module.readingExamples('mim',10)}:initial,onChange:()=>{readingCleared=false;}});}).catch(error=>{if(!disposed)setUiMessage(form.querySelector('[role=alert]'),uiMessage('lessonUi.homeworkReadingFailed'));throw error;}).finally(()=>{readingLoading=null;});return readingLoading;};readingRoot.querySelector('button').onclick=()=>void openReading(null,true).catch(()=>{});if(initial?.readingCheck)void openReading(initial.readingCheck).catch(()=>{});
 form.querySelector('[data-cancel]').onclick=()=>{if(!disposed)onCancel();};
 form.querySelector('[data-clear]')?.addEventListener('click',()=>{text.value='';due.value='';readingEditor?.disable();readingCleared=true;setUiMessage(error,uiMessage('lessonUi.homeworkWillRemove'));text.focus();});
 form.onsubmit=async event=>{event.preventDefault();if(disposed||button.disabled)return;if(text.value.length>2000){setUiMessage(error,uiMessage('lessonUi.homeworkTooLong'));return;}if(readingLoading){button.disabled=true;try{await readingLoading;}catch{button.disabled=false;return;}button.disabled=false;}if(disposed||!form.isConnected)return;let readingCheck;try{readingCheck=readingCleared?null:readingEditor?readingEditor.value():initial?.readingCheck||null;}catch(e){setUiMessage(error,lessonErrorMessage(e));return;}let content=text.value.trim();if(readingCheck&&!content)content='Прочитайте сочетания после пройденной буквы и отправьте голосовую запись до следующего занятия.';if(!content&&due.value){setUiMessage(error,uiMessage('lessonUi.homeworkTextOrClearDue'));return;}if(!form.checkValidity())return;button.disabled=true;setUiMessage(error,'');try{await onSave(content?{text:content,dueDate:due.value||null,...(readingCheck?{readingCheck}:{})}:null,lesson.homeworkRevision||0);}catch(e){if(!disposed&&form.isConnected){setUiMessage(error,lessonErrorMessage(e,'lessonUi.homeworkSaveFailed'));button.disabled=false;}}};
 const offLanguage=bindLessonsUi(root);text.focus();return()=>{disposed=true;offLanguage();readingEditor?.dispose();form.onsubmit=null;root.replaceChildren();};
}
